import React, { useState } from "react";
import "./SpendingPriority.css";

const categories = [
  "Food & Groceries",
  "Shopping",
  "Bills",
  "Health",
  "Entertainment",
  "Transport"
];

function SpendingPriority({ onNext, updateData }) {
  const [values, setValues] = useState({});

  const handleChange = (category, value) => {
    setValues({ ...values, [category]: Number(value) });
  };

  const handleContinue = () => {
    updateData({ spendingPriority: values });
    onNext();
  };

  return (
    <div className="income-container">
      <h2 className="income-title">Spending Priorities</h2>

      <div className="income-grid">
        {categories.map((cat) => (
          <div key={cat} className="income-card">
            <div className="income-name">{cat}</div>

            <input
              type="range"
              min="0"
              max="5"
              value={values[cat] || 0}
              onChange={(e) => handleChange(cat, e.target.value)}
            />
          </div>
        ))}
      </div>

      <button className="next-button" onClick={handleContinue}>
        Continue
      </button>
    </div>
  );
}

export default SpendingPriority;
